                elif d<0: p=1.0/(1.0+__import__('math').exp(max(-30,d/18)))
                else: p=.5
                x[u]=0 if rng.random()<p else 1
        x,_=improve(x)
        val=cutval(x)
        if val>bestval: bestval=val; best=x[:]
        it+=1
